import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const i="/assets/image%20(10).MgVabLG4.png",s="/assets/image%20(11).CAEQ4Ca0.png",n="/assets/image%20(12).D7bctiEo.png",b=JSON.parse('{"title":"Wisdom Capital","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/wisdom-capital.md","filePath":"connect-brokers/brokers/wisdom-capital.md"}'),p={name:"connect-brokers/brokers/wisdom-capital.md"};function l(d,e,c,h,g,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="wisdom-capital" tabindex="-1">Wisdom Capital <a class="header-anchor" href="#wisdom-capital" aria-label="Permalink to &quot;Wisdom Capital&quot;">​</a></h1><p>Wisdom Capital provides API access through the Symphony Fintech XTS platform. This guide helps you integrate Wisdom Capital with Tradeboard for both order execution and market data streaming.</p><hr><h3 id="step-1-create-api-applications" tabindex="-1">Step 1: Create API Applications <a class="header-anchor" href="#step-1-create-api-applications" aria-label="Permalink to &quot;Step 1: Create API Applications&quot;">​</a></h3><p>Login to the <a href="https://trade.wisdomcapital.in/dashboard#!/login" target="_blank" rel="noreferrer">Wisdom Capital Developer Portal</a>.</p><p>After logging in:</p><ol><li>Go to <code>My App</code> &gt; <code>Create New Application</code></li><li>You need to create two applications: <ul><li>One for <strong>Interactive Order API</strong></li><li>One for <strong>Market Data API</strong></li></ul></li></ol><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><h4 id="application-setup" tabindex="-1">Application Setup: <a class="header-anchor" href="#application-setup" aria-label="Permalink to &quot;Application Setup:&quot;">​</a></h4><p>For each app, fill in the following:</p><ul><li><strong>App Name</strong>: Tradeboard</li><li><strong>App Description</strong>: Tradeboard</li><li><strong>Select API Package</strong>: Choose <code>Interactive Order API</code> or <code>Market Data API</code> depending on the app.</li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>Repeat the process for both API packages.</p><p>Once submitted, wait for the apps to be <strong>approved</strong>. The API status will show as <strong>Active</strong> once approved.</p><figure><img src="'+n+`" alt=""><figcaption></figcaption></figure><hr><h3 id="step-2-setup-environment-variables" tabindex="-1">Step 2: Setup Environment Variables <a class="header-anchor" href="#step-2-setup-environment-variables" aria-label="Permalink to &quot;Step 2: Setup Environment Variables&quot;">​</a></h3><p>Refer to the <code>.sample.env</code> file in Tradeboard and prepare your <code>.env</code> with the following structure:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;YOUR_WISDOM_ORDER_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;YOUR_ORDER_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BROKER_API_KEY_MARKET = &#39;YOUR_WISDOM_MARKET_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET_MARKET = &#39;YOUR_MARKET_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/wisdom/callback&#39;</span></span></code></pre></div><p>Replace placeholder values with actual credentials obtained after app approval.</p><hr><h3 id="step-3-start-tradeboard" tabindex="-1">Step 3: Start Tradeboard <a class="header-anchor" href="#step-3-start-tradeboard" aria-label="Permalink to &quot;Step 3: Start Tradeboard&quot;">​</a></h3><p>Ensure <code>.env</code> is correctly configured and that both APIs (order and market data) are active. Then, start Tradeboard.</p><blockquote><p>You can now place live orders and get real-time market data via Wisdom Capital’s XTS API inside Tradeboard.</p></blockquote><hr><h3 id="final-note" tabindex="-1">Final Note <a class="header-anchor" href="#final-note" aria-label="Permalink to &quot;Final Note&quot;">​</a></h3><p>Integrating Tradeboard with Wisdom Capital&#39;s XTS API gives you access to real-time market data and order execution in a programmable environment. Follow best practices: keep your API keys secure, implement appropriate error handling, and regularly monitor your API usage to ensure a smooth trading experience.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/wisdom/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,30)])])}const _=a(p,[["render",l]]);export{b as __pageData,_ as default};
